import { readFile } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";
import { CaseSummary } from "@/lib/api/schema";
import { apiMode } from "@/lib/api/source";

/**
 * Fixtures mode only. The published CRC sample holds no referral the unit has not answered, so the inbox adds these
 * synthetic ones (web/data/referral-inbox-synthetic-v2.json) to show its Accept, conditions and Return controls. They are
 * kept out of the API samples so the other pages' counts stay the run's. The live API never gets them.
 * Generated by pipeline/referral_inbox_fixture_test.go through the canonical facts/reducer/materializer/read handler;
 * referral-inbox-provenance-v2.json records inputs, signed currents and hashes. Version2 supplies explicit completed
 * acknowledgement status; the original version1 record and helper remain immutable historical software evidence.
 * These are synthetic controls, not medical evidence.
 */
export async function syntheticReferrals(q: string): Promise<CaseSummary[]> {
  if (apiMode() === "live") return [];
  const file = path.join(process.cwd(), "data", "referral-inbox-synthetic-v2.json");
  const cases = z.array(CaseSummary).parse(JSON.parse(await readFile(file, "utf8")));
  return cases.filter((c) => c.id.includes(q));
}
